const sources = message.parts.filter(
  (part) => part.type === 'source-url'
);

{sources.length > 0 && (
  <Sources>
    <Sources.Trigger count={sources.length} />
    <Sources.Content>
      {sources.map((part) => (
        <Sources.Source
          key={part.sourceId}
          href={part.url}
          title={part.title}
        />
      ))}
    </Sources.Content>
  </Sources>
)}
